mapper.select:
SELECT b.id, c.name, b.author, b.title, b.view_count, b.created_at, b.updated_at, EXISTS( SELECT 1 FROM attachment a WHERE a.board_id = b.id ) AS hasAttachment FROM board b INNER JOIN category c ON c.id = b.category_id
AND ( b.title LIKE CONCAT('%', #{keyword}, '%') OR b.content LIKE CONCAT('%', #{keyword}, '%') OR b.author LIKE CONCAT('%', #{keyword}, '%') )
AND b.category_id = #{categoryId}
AND b.created_at >= #{startDate}
AND b.created_at <= #{endDate}
ORDER BY b.created_at DESC

SELECT EXISTS(
    SELECT 1 FROM board WHERE id = #{id}
    )

mapper.update:
UPDATE board
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE board
SET category_id = #{categoryId},
    title        = #{title},
    content      = #{content},
    updated_at   = #{updatedAt}
WHERE id = #{id}
